using REPOJP.StageRoles;
using Photon.Pun;
using UnityEngine;
using UnityEngine.SceneManagement;
using ExitGames.Client.Photon;
int checks=0; void Check(bool ok,string label) { checks++;if(!ok)throw new Exception(label); }
const string magic="RoleShuffle.UpgradeDetails.1";
var controller=new StageRoleController(); var sync=new UpgradeBreakdownSync();sync.Initialize(controller);
EventData Event(int sender,string kind,string nonce,string body)=>new(){Sender=sender,CustomData=new object[]{magic,kind,nonce,body}};
string n=new('a',32);
sync.OnEvent(Event(2,"request",n,"stage"));
Check(PhotonNetwork.Sent.Count==1&&PhotonNetwork.Sent[0].Actor==2&&controller.Requested.SequenceEqual(new[]{2}),"Host looks up sender and replies only to sender");
Check(PhotonNetwork.Sent[0].Data.Length==4&&UpgradeBreakdownCodec.Decode((string)PhotonNetwork.Sent[0].Data[3])!.Rows.Single().Actual==5,"Response contains only requester snapshot");
sync.OnEvent(Event(2,"request",n,"stage"));Check(controller.Reads==1,"Rapid requests throttled");
sync.OnEvent(Event(3,"request",n,"stage"));Check(controller.Reads==2&&PhotonNetwork.Sent.Last().Actor==3,"Separate per-player rate limit");
foreach(var request in new[]{Event(99,"request",n,"stage"),Event(2,"request",n,"other"),Event(2,"request","bad","stage"),Event(2,"reply",n,"stage")})sync.OnEvent(request);
Check(controller.Reads==2,"Unknown actor, scene and malformed request rejected");
PhotonNetwork.Sent.Clear();PhotonNetwork.IsMasterClient=false;Time.unscaledTime=10;
Check(UpgradeBreakdownSync.ReadLocalPlayer()==null&&PhotonNetwork.Sent.Single().Actor==1,"Guest asks only master");
var requestData=PhotonNetwork.Sent.Single().Data;string nonce=(string)requestData[2];
string payload=UpgradeBreakdownCodec.Encode(new(StageRole.Tank,new[]{new UpgradeBreakdownRow("Health",0,0,3,0,0,0,3)}));
sync.OnEvent(Event(3,"reply",nonce,payload));Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Peer cannot forge master's snapshot");
sync.OnEvent(Event(1,"reply",n,payload));Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Old nonce rejected");
Time.unscaledTime=12;Check(UpgradeBreakdownSync.ReadLocalPlayer()==null&&PhotonNetwork.Sent.Count==1,"Two-second latency keeps outstanding nonce");
sync.OnEvent(Event(1,"reply",nonce,payload));Check(UpgradeBreakdownSync.ReadLocalPlayer()?.Role==StageRole.Tank,"Slow valid reply accepted");
sync.OnEvent(Event(1,"reply",nonce,payload.Replace("Tank","Runner")));Check(PhotonNetwork.Sent.Count==1,"Reply nonce consumed once");
int reads=controller.Reads;for(int i=0;i<10;i++)_ = UpgradeBreakdownSync.Signature;
Check(controller.Reads==reads&&PhotonNetwork.Sent.Count==1,"Rendering never mutates host state or repeats requests");
Time.unscaledTime=18;Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Expired snapshot hidden");
requestData=PhotonNetwork.Sent.Last().Data;nonce=(string)requestData[2];sync.OnEvent(Event(1,"reply",nonce,payload));
Check(UpgradeBreakdownSync.ReadLocalPlayer()!=null,"Refresh restores data");
SceneManager.Name="shop";Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Stage transition clears cached data");
sync.OnEvent(Event(1,"reply",nonce,payload));Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Old scene reply cannot repopulate");
requestData=PhotonNetwork.Sent.Last().Data;nonce=(string)requestData[2];sync.OnEvent(Event(1,"reply",nonce,payload));
PhotonNetwork.CurrentRoom=new();Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Reconnect room clears data");
sync.OnEvent(Event(1,"reply",nonce,payload));Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Previous room nonce rejected");
PhotonNetwork.MasterClient=new(3);UpgradeBreakdownSync.ReadLocalPlayer();Check(PhotonNetwork.Sent.Last().Actor==3,"Authority change targets new host");
nonce=(string)PhotonNetwork.Sent.Last().Data[2];sync.OnEvent(Event(1,"reply",nonce,payload));Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Former host ignored");
sync.OnEvent(Event(3,"reply",nonce,"corrupt"));Check(UpgradeBreakdownSync.ReadLocalPlayer()==null,"Invalid payload hidden");
sync.OnEvent(Event(3,"reply",nonce,payload));Check(UpgradeBreakdownSync.ReadLocalPlayer()!=null,"Valid replacement host reply accepted");
SemiFunc.Multiplayer=false;Time.unscaledTime=30;PhotonNetwork.Sent.Clear();
Check(UpgradeBreakdownSync.ReadLocalPlayer()!=null&&PhotonNetwork.Sent.Count==0,"Solo reads locally without network");
Console.WriteLine($"PASS: {checks} targeted upgrade-detail transport checks with simulated Photon endpoints.");
